import { getLanguage } from 'obsidian';

export type Locale = 'zh-CN' | 'en' | 'zh-TW' | 'ja' | 'ko' | 'es' | 'fr' | 'de';

/** Maps the Obsidian interface language onto the eight locales this plugin ships. */
export function locale(): Locale {
  const lang = (getLanguage() || 'en').toLowerCase();
  if (lang.startsWith('zh')) return lang.includes('tw') || lang.includes('hk') || lang.includes('mo') || lang.includes('hant') ? 'zh-TW' : 'zh-CN';
  if (lang.startsWith('ja')) return 'ja';
  if (lang.startsWith('ko')) return 'ko';
  if (lang.startsWith('es')) return 'es';
  if (lang.startsWith('fr')) return 'fr';
  if (lang.startsWith('de')) return 'de';
  return 'en';
}

