export type MessageKey = (typeof M)[number][0];

const build = (index: number) => Object.fromEntries(M.map(row => [row[0], row[index]])) as Record<MessageKey, string>;
const EN = build(2);
const TABLES: Record<Locale, Record<MessageKey, string>> = { 'zh-CN': build(1), en: EN, 'zh-TW': build(3), ja: build(4), ko: build(5), es: build(6), fr: build(7), de: build(8) };

/** Translates a UI string into the current Obsidian language; {placeholders} are filled from vars. */
export function t(key: MessageKey, vars?: Record<string, string | number>): string {
  let text: string = TABLES[locale()][key] || EN[key] || key;
  if (vars) for (const [name, value] of Object.entries(vars)) text = text.split('{' + name + '}').join(String(value));
  return text;
}

/** Error whose message is already a localized, user-facing string and should be shown as-is. */
export class LocalizedError extends Error {}

/** Throws a localized, user-facing error. */
export function fail(key: MessageKey, vars?: Record<string, string | number>): never {
  throw new LocalizedError(t(key, vars));
}

export function isLocalizedError(error: unknown): boolean {
  return error instanceof LocalizedError;
}

const DIVIDER_KEYS: Record<string, MessageKey> = {
  '微信公众号': 'divider.wechat', '小宇宙': 'divider.xiaoyuzhou', 'YouTube': 'divider.youtube',
  'Newsletter': 'divider.newsletter', '资讯': 'divider.news', '博客与网站': 'divider.blogs',
};

/** Display label for a curated channel divider; unknown custom dividers stay as-is. */
export function dividerLabel(divider: string): string {
  const key = DIVIDER_KEYS[divider];
  return key ? t(key) : divider;
}

const KIND_KEYS: Record<string, MessageKey> = { wechat: 'discovery.kind.wechat', podcast: 'discovery.kind.podcast', blogs: 'discovery.kind.blogs', more: 'discovery.kind.more' };

/** Display label for a discovery source kind. */
export function kindLabel(kind: string): string {
  const key = KIND_KEYS[kind];
  return key ? t(key) : kind;
}

const COLLECTION_KEYS: Record<string, MessageKey> = { wechat: 'discovery.collection.wechat', podcast: 'discovery.collection.podcast', blogs: 'discovery.collection.blogs' };

/** Display label for a discovery collection tab. */
export function collectionLabel(collection: string): string {
  const key = COLLECTION_KEYS[collection];
  return key ? t(key) : collection;
}

/** Renders the API's English relative dates ("over 3 days ago") in the interface language. */
export function relativeTime(raw: string): string {
  const value = raw.trim();
  if (/^today$/i.test(value)) return t('time.today');
  if (/^yesterday$/i.test(value)) return t('time.yesterday');
  const match = /^(over|almost|about)?\s*(\d+)\s*(day|week|month|year)s? ago$/i.exec(value);
  if (!match) return raw;
  const n = Number(match[2]), unit = match[3].toLowerCase(), mod = (match[1] || '').toLowerCase();
  const loc = locale();
  if (loc === 'en') return raw;
  if (loc === 'zh-CN' || loc === 'zh-TW') {
    const tw = loc === 'zh-TW';
    const units: Record<string, string> = { day: '天', week: tw ? '週' : '周', month: tw ? '個月' : '个月', year: '年' };
    const prefix = mod === 'almost' ? '近 ' : mod === 'about' ? (tw ? '約 ' : '约 ') : '';
    return prefix + n + ' ' + (units[unit] || unit) + (mod === 'over' ? '多' : '') + '前';
  }
  if (loc === 'ja') {
    const units: Record<string, string> = { day: '日', week: '週間', month: 'か月', year: '年' };
    if (mod === 'over') return n + (units[unit] || unit) + '以上前';
    return (mod === 'almost' ? 'ほぼ' : mod === 'about' ? '約' : '') + n + (units[unit] || unit) + '前';
  }
  if (loc === 'ko') {
    const units: Record<string, string> = { day: '일', week: '주', month: '개월', year: '년' };
    if (mod === 'over') return n + (units[unit] || unit) + ' 이상 전';
    return (mod === 'almost' ? '거의 ' : mod === 'about' ? '약 ' : '') + n + (units[unit] || unit) + ' 전';
  }
  if (loc === 'es') {
    const one: Record<string, string> = { day: 'día', week: 'semana', month: 'mes', year: 'año' };
    const many: Record<string, string> = { day: 'días', week: 'semanas', month: 'meses', year: 'años' };
    const unitText = (n === 1 ? one : many)[unit] || unit;
    if (mod === 'over') return 'hace más de ' + n + ' ' + unitText;
    return 'hace ' + (mod === 'almost' ? 'casi ' : mod === 'about' ? 'unos ' : '') + n + ' ' + unitText;
  }
  if (loc === 'fr') {
    const one: Record<string, string> = { day: 'jour', week: 'semaine', month: 'mois', year: 'an' };
    const many: Record<string, string> = { day: 'jours', week: 'semaines', month: 'mois', year: 'ans' };
    const unitText = (n === 1 ? one : many)[unit] || unit;
    if (mod === 'over') return 'il y a plus de ' + n + ' ' + unitText;
    return 'il y a ' + (mod === 'almost' ? 'presque ' : mod === 'about' ? 'environ ' : '') + n + ' ' + unitText;
  }
  const one: Record<string, string> = { day: 'Tag', week: 'Woche', month: 'Monat', year: 'Jahr' };
  const many: Record<string, string> = { day: 'Tagen', week: 'Wochen', month: 'Monaten', year: 'Jahren' };
  const unitText = (n === 1 ? one : many)[unit] || unit;
  if (mod === 'over') return 'vor über ' + n + ' ' + unitText;
  return 'vor ' + (mod === 'almost' ? 'fast ' : mod === 'about' ? 'etwa ' : '') + n + ' ' + unitText;
}
